                new GrowthNodeDefinition("common.resonance.03", GrowthOwner.Common, "공명과 궁극 운용", "화음", "서로 다른 두 원인으로 공명을 얻은 다음 궁극기에 연결 효과 한 개를 붙인다. 같은 대상을 복제 궤적으로 여러 번 맞히는 것은 서로 다른 원인이 아니다.", "", 1, "규칙 변형", "", "", "", "", 0, new[] { "common.resonance.01" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("common.resonance.04", GrowthOwner.Common, "공명과 궁극 운용", "불완전 개방", "공명 4로 약화된 궁극기를 발동할 수 있다. 지속·추가 행동·변신형은 미리 정한 축약판을 쓰며 완전 궁극기와 동급 효과를 주지 않는다.", "", 1, "규칙 변형", "", "", "", "", 0, new[] { "common.resonance.02" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("common.resonance.05", GrowthOwner.Common, "공명과 궁극 운용", "공명 차폐", "가득 찬 공명을 소비하지 않고 응축하면 한 번의 방어 장막을 만들 수 있다. 그 응축에서 공명 1을 쓰고 원래 체력 비용도 지불한다.", "", 1, "규칙 변형", "", "", "", "", 0, new[] { "common.resonance.02" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("common.resonance.06", GrowthOwner.Common, "공명과 궁극 운용", "후렴", "궁극기로 만든 지점 하나를 다음 턴의 기준점 후보로 남긴다. 궁극기 피해·회복·해제 효과는 그 지점에 남지 않는다.", "", 1, "규칙 변형", "", "", "", "", 0, new[] { "common.resonance.03" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("common.resonance.07", GrowthOwner.Common, "공명과 궁극 운용", "이중 악장", "공명 6 궁극기를 두 번의 공명 3 반궁극기로 분해한다. 두 번째는 첫 번째와 정해진 연결 형태로만 쓰며 첫 악장과 같은 전체 효과를 반복하지 않는다.", "", 2, "공통 핵심", "", "", "common.resonance.keystone", "", 0, new[] { "common.resonance.01" }, 2, new[] { "common.resonance.02", "common.resonance.03", "common.resonance.04", "common.resonance.05", "common.resonance.06" }, GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("common.resonance.08", GrowthOwner.Common, "공명과 궁극 운용", "대공명", "공명 저장 상한을 9로 바꾼다. 6에서는 기존 궁극기, 9에서는 한 턴 준비가 드러나는 확장 형태를 선택하며 기본 획득량은 그대로다.", "", 2, "공통 핵심", "", "", "common.resonance.keystone", "", 0, new[] { "common.resonance.01" }, 2, new[] { "common.resonance.02", "common.resonance.03", "common.resonance.04", "common.resonance.05", "common.resonance.06" }, GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("common.fragments.01", GrowthOwner.Common, "파편의 사용법", "마지막 주석", "방출 전 한 번, 마지막 미확정 파편의 수학 변환을 적용할지 건너뛸지 선택한다. 카드는 소비하고 카드 능력은 유지하되 생략한 파편의 조립 위력은 제외한다. 모든 전후 도안과 카드 정보는 노드 없이도 무료로 표시한다.", "", 1, "규칙 변형", "", "", "", "", 0, System.Array.Empty<string>(), 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("common.fragments.02", GrowthOwner.Common, "파편의 사용법", "순서 역전", "한 조립에서 한 번, 마지막 두 미확정 파편의 순서를 바꿀 수 있다. 완성 식과 주파수를 처음부터 다시 검사하고 사용·드로우 이력은 그대로 유지한다.", "", 1, "규칙 변형", "", "", "", "", 0, new[] { "common.fragments.01" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("common.fragments.03", GrowthOwner.Common, "파편의 사용법", "수학적 생략", "같은 수학 변환을 두 번 연속 놓았을 때 두 번째 파편을 계산에서만 잠시 생략하는 선택지를 준다. 그 카드의 위력·능력도 빠지며 카드는 여전히 소비한다.", "", 1, "규칙 변형", "", "", "", "", 0, new[] { "common.fragments.01" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("common.fragments.04", GrowthOwner.Common, "파편의 사용법", "괄호의 문", "최대 4장으로 된 짧은 구간의 순서를 거꾸로 해석할 수 있다. 원래 합성을 몰래 교환법칙처럼 처리하지 않고 결과를 별도 미리보기로 보여 준다.", "", 1, "규칙 변형", "", "", "", "", 0, new[] { "common.fragments.02" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("common.fragments.05", GrowthOwner.Common, "파편의 사용법", "종결 서명", "마지막 파편이 기준점 이동 계열이면 다음 기술의 착지점을 그 기준점 근처로 선택할 수 있다. 이동 지형 검사와 기술 행동 한도를 그대로 따른다.", "", 1, "규칙 변형", "", "", "", "", 0, new[] { "common.fragments.02" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("common.fragments.06", GrowthOwner.Common, "파편의 사용법", "변환 잔향", "생략한 변환을 다음 새 조립의 첫 파편에 한 번만 적용할 수 있다. 재사용 카드 능력·드로우는 없고 주파수 제한을 넘으면 저장 효과를 소비하지 않고 적용을 거절한다.", "", 1, "규칙 변형", "", "", "", "", 0, new[] { "common.fragments.03" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("common.fragments.07", GrowthOwner.Common, "파편의 사용법", "삼행시", "한 방출에 최대 3장만 넣는 대신 첫·중간·마지막 파편에 시작·연결·종결 역할을 부여한다. 긴 조립 보너스를 포기하며 역할 효과는 수학 계열별로 정해진다.", "", 2, "공통 핵심", "", "", "common.fragments.keystone", "", 0, new[] { "common.fragments.01" }, 2, new[] { "common.fragments.02", "common.fragments.03", "common.fragments.04", "common.fragments.05", "common.fragments.06" }, GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("common.fragments.08", GrowthOwner.Common, "파편의 사용법", "장편 기록", "6장 이상 조립한 식은 완성 직전 도안 하나를 다음 턴의 비교 대상으로 남긴다. 다음 식이 실제로 이전 도안과 다른 영역의 적을 맞혀야 연계 보상을 받고 같은 식 복제로는 얻지 않는다.", "", 2, "공통 핵심", "", "", "common.fragments.keystone", "", 0, new[] { "common.fragments.01" }, 2, new[] { "common.fragments.02", "common.fragments.03", "common.fragments.04", "common.fragments.05", "common.fragments.06" }, GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.inscription.core", GrowthOwner.Ian, "핵심 능력", "균열의 기록자", "직접 기술로 표시한 적을 뒤따르는 직접 작도로 맞히면 새 파열을 남긴다. 같은 종류만 반복해 때리면 추가 기록은 없다. 새 파열은 그다음 실제 작도에서 소비되며 이번 피해에 소급해서 더하지 않는다.", "", 1, "핵심 능력", "", "", "이안.identity", "", 0, System.Array.Empty<string>(), 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.inscription.m1", GrowthOwner.Ian, "핵심 능력", "역순 기록", "작도 뒤 기술로 기록하는 순서에서도 파열을 남긴다. 이미 같은 행동 사슬에서 기록한 적은 다시 기록하지 않는다.", "", 1, "핵심 능력 특성", "", "", "", "ian.inscription", 2, new[] { "ian.inscription.core" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.inscription.m2", GrowthOwner.Ian, "핵심 능력", "부서진 문장", "파열 적을 처치하면 남은 파열 일부를 이안의 현재 식이 닿는 다른 적 한 명에게 옮긴다. 다른 적이 없으면 다음 기술의 단일 대상 조건으로 보관한다.", "", 1, "핵심 능력 특성", "", "", "", "ian.inscription", 2, new[] { "ian.inscription.core" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.inscription.m3", GrowthOwner.Ian, "핵심 능력", "결산 유예", "파열을 지금의 작도에서 소비할지 다음 작도까지 남길지 선택한다. 보류한 파열은 이번 피해에 더하지 않고 저장량 상한을 유지한다.", "", 1, "핵심 능력 특성", "", "", "", "ian.inscription", 2, new[] { "ian.inscription.core" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.archive.core", GrowthOwner.Ian, "핵심 능력", "잔상의 기록자", "마지막 유효 방출의 세계 좌표 도안을 하나, 두 플레이어 턴 동안 보관한다. 잔상은 기술이나 연계로 호출하기 전에는 공격하지 않으며 원본 카드 능력을 소유하지 않는다.", "", 1, "핵심 능력", "", "", "이안.identity", "", 0, System.Array.Empty<string>(), 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.archive.m1", GrowthOwner.Ian, "핵심 능력", "이중 장부", "도안 두 개 중 하나를 선택할 수 있다. 같은 방출에서 양쪽을 공짜로 재현하지 않으며 두 도안은 전투가 끝나면 사라진다.", "", 1, "핵심 능력 특성", "", "", "", "ian.archive", 2, new[] { "ian.archive.core" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.archive.m2", GrowthOwner.Ian, "핵심 능력", "현장 보존", "기준점 카드로 현재 식을 옮겨도 저장 도안은 원래 세계 좌표를 유지한다. 현재 식과 옛 식의 교점을 기술 대상 지점으로 사용할 수 있다.", "", 1, "핵심 능력 특성", "", "", "", "ian.archive", 2, new[] { "ian.archive.core" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.archive.m3", GrowthOwner.Ian, "핵심 능력", "먹빛 필사", "빈 잔상 슬롯에서 응축하면 아직 공격하지 않은 조립도 도안으로 저장할 수 있다. 이 도안을 재현해도 미발동 카드 능력·드로우는 발생하지 않는다.", "", 1, "핵심 능력 특성", "", "", "", "ian.archive", 2, new[] { "ian.archive.core" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.citadel.core", GrowthOwner.Ian, "핵심 능력", "흑유리의 수호자", "자가 적중으로 생긴 보호막 중 남은 일부를 다음 턴까지 보존하는 대신 즉시 회복의 일부를 포기한다. 보존 보호막은 기술로 벽·쐐기에 투자할 수 있고 총량에 상한이 있다.", "", 1, "핵심 능력", "", "", "이안.identity", "", 0, System.Array.Empty<string>(), 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.citadel.m1", GrowthOwner.Ian, "핵심 능력", "투명한 대가", "쐐기나 벽 설치 때 보존 보호막을 정해진 양 소모하여 설치물 한 개를 강화한다. 설치 취소나 소멸로 이미 쓴 보호막은 돌아오지 않는다.", "", 1, "핵심 능력 특성", "", "", "", "ian.citadel", 2, new[] { "ian.citadel.core" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.citadel.m2", GrowthOwner.Ian, "핵심 능력", "금 간 방어", "실제 적 공격이 보존 보호막을 깨면 공격자에게 파열을 남긴다. 응축 비용·자해·보호막 수명 만료에는 발동하지 않는다.", "", 1, "핵심 능력 특성", "", "", "", "ian.citadel", 2, new[] { "ian.citadel.core" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.citadel.m3", GrowthOwner.Ian, "핵심 능력", "안전한 응축", "보존 보호막이 있는 동안 응축으로 자신의 최근 도안에 작은 방어 흔적을 남긴다. 응축 체력 비용은 여전히 체력으로 지불하며 반격 재생은 하지 않는다.", "", 1, "핵심 능력 특성", "", "", "", "ian.citadel", 2, new[] { "ian.citadel.core" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.orbit.core", GrowthOwner.Luna, "핵심 능력", "궤도의 조율자", "조립 중 실제 이동을 확정하면 한 번에 한해 기준점도 이동량만큼 함께 옮길 수 있다. 고정해서 남길 수도 있다. 카드 사용 순서와 수학 변환은 그대로다.", "", 1, "핵심 능력", "", "", "루나.identity", "", 0, System.Array.Empty<string>(), 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.orbit.m1", GrowthOwner.Luna, "핵심 능력", "접선 보행", "이동 목적지 선택 때 현재 궤적의 가까운 점을 따라가는 경로를 제안한다. 보이는 곡선을 이동로로 쓰되 전체 거리와 충돌 한도를 지킨다.", "", 1, "핵심 능력 특성", "", "", "", "luna.orbit", 2, new[] { "luna.orbit.core" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.orbit.m2", GrowthOwner.Luna, "핵심 능력", "반대편의 달", "이동으로 기준점을 옮길 때 자기 위치와 반대 방향으로 이동량을 적용할 수 있다. 실제 결과를 확정 전 미리보기로 보여 준다.", "", 1, "핵심 능력 특성", "", "", "", "luna.orbit", 2, new[] { "luna.orbit.core" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.orbit.m3", GrowthOwner.Luna, "핵심 능력", "원심 서명", "일반 이동으로 조준 원 밖으로 나간 뒤 같은 턴 적을 작도로 맞히면 다음 기술의 외곽 표식을 얻는다. 이동 취소로 표식을 얻거나 유지하지 않는다.", "", 1, "핵심 능력 특성", "", "", "", "luna.orbit", 2, new[] { "luna.orbit.core" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.phase.core", GrowthOwner.Luna, "핵심 능력", "월상의 연주자", "적 또는 자신을 실제로 맞힌 방출마다 삭→상현→만월을 순환한다. 삭은 다음 기술의 공격 표식, 상현은 궤도 조정, 만월은 다음 자가 적중 방어에 특화하며 빈 방출은 순환하지 않는다.", "", 1, "핵심 능력", "", "", "루나.identity", "", 0, System.Array.Empty<string>(), 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.phase.m1", GrowthOwner.Luna, "핵심 능력", "월상 정박", "전투당 두 번, 방출 뒤 월상을 한 단계 유지할 수 있다. 유지한 방출에서는 월상 순환 보상을 다시 얻지 않는다.", "", 1, "핵심 능력 특성", "", "", "", "luna.phase", 2, new[] { "luna.phase.core" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.phase.m2", GrowthOwner.Luna, "핵심 능력", "삭의 되풀이", "궁극기 종료 후 첫 유효 방출의 월상을 삭으로 고정하는 선택지를 준다. 기존 월상의 보상을 이중으로 받지는 않는다.", "", 1, "핵심 능력 특성", "", "", "", "luna.phase", 2, new[] { "luna.phase.core" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.phase.m3", GrowthOwner.Luna, "핵심 능력", "만월의 틈", "만월에서 자기와 적을 함께 맞히면 다음 상현 기술이 이동 없이도 궤도를 한 번 조정한다. 보상은 한 번 저장되며 추가 일반 이동은 아니다.", "", 1, "핵심 능력 특성", "", "", "", "luna.phase", 2, new[] { "luna.phase.core" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.binary.core", GrowthOwner.Luna, "핵심 능력", "쌍성의 관측자", "첫 일반 이동의 출발점에 관측 위성을 하나 남긴다. 다음 조립의 시작점을 몸과 위성 중 고를 수 있고, 위성을 맞힌 작도로 자가 효과를 대신 받을 수 있다. 몸과 위성이 동시에 맞아도 한 번이다.", "", 1, "핵심 능력", "", "", "루나.identity", "", 0, System.Array.Empty<string>(), 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.binary.m1", GrowthOwner.Luna, "핵심 능력", "이동 관측", "일반 이동을 확정할 때 위성을 옛 위치에 남길지 새 출발점으로 옮길지 고른다. 입력 취소 시 위성도 원복한다.", "", 1, "핵심 능력 특성", "", "", "", "luna.binary", 2, new[] { "luna.binary.core" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.binary.m2", GrowthOwner.Luna, "핵심 능력", "빛의 삼각형", "몸·위성·프리즘을 실제로 잇는 식이면 세 점 중 하나를 다음 기술의 지정 위치로 쓸 수 있다. 세 점을 자동으로 공격선으로 채우지는 않는다.", "", 1, "핵심 능력 특성", "", "", "", "luna.binary", 2, new[] { "luna.binary.core" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.binary.m3", GrowthOwner.Luna, "핵심 능력", "쌍성 거리", "위성을 멀리 유지하는 동안 방어 대리 적중 범위를 줄이고 공격 기준점으로 특화할 수 있다. 가까이 회수하면 일반 대리 적중으로 돌아오며 전투 중 전환은 기술 행동을 쓴다.", "", 1, "핵심 능력 특성", "", "", "", "luna.binary", 2, new[] { "luna.binary.core" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.triple.form", GrowthOwner.Ian, "전투 기술 / 유리 쇄도", "삼중 유리길", "지정 방향으로 이동하며 중심선과 양옆의 세 선을 남긴다. 적 한 명이 여러 선에 닿아도 기본 기술 피해는 한 번이고, 선은 다음 방출까지 연결 대상으로 남는다.", "넓게 맞히지만 단일 대상 폭발력과 정밀한 착지 선택은 집행형보다 낮다.", 1, "전투 기술 형태", "전투 기술", "유리 쇄도", "", "", 0, System.Array.Empty<string>(), 0, System.Array.Empty<string>(), GrowthImplementationStatus.PrototypePartial),
                new GrowthNodeDefinition("ian.triple.m1", GrowthOwner.Ian, "전투 기술 / 유리 쇄도", "굴절 경유", "중심선이 프리즘을 실제로 지나면 그 지점에서 옆 선의 방향을 꺾는다. 분기 수는 세 개로 유지하며 프리즘마다 재분기하지 않는다.", "", 1, "기술 특성", "", "", "", "ian.triple", 2, new[] { "ian.triple.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.triple.m2", GrowthOwner.Ian, "전투 기술 / 유리 쇄도", "보호 반사", "뒤따르는 그래프가 남은 유리길과 자신을 함께 지나면 보호막을 얻는다. 유리길만 맞히거나 자신만 맞히면 기술 보상은 없다.", "", 1, "기술 특성", "", "", "", "ian.triple", 2, new[] { "ian.triple.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.triple.m3", GrowthOwner.Ian, "전투 기술 / 유리 쇄도", "교차 봉합", "세 선 중 서로 다른 두 선을 한 그래프로 연결하면 둘 사이에 작은 연결 파열을 한 번 만든다. 원래 기술을 세 번 재사용하는 효과는 아니다.", "", 1, "기술 특성", "", "", "", "ian.triple", 2, new[] { "ian.triple.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.triple.awaken", GrowthOwner.Ian, "전투 기술 / 유리 쇄도", "흑유리 회랑", "세 유리길을 다음 적 행동까지 유지하는 회랑으로 진화한다. 그래프와 회랑이 함께 닿은 적에게 출력을 집중하거나, 두 영역으로 나눠 공격하는 방식을 방출 전에 선택한다.", "", 2, "기술 각성", "", "", "", "", 0, new[] { "ian.triple.form" }, 2, new[] { "ian.triple.m1", "ian.triple.m2", "ian.triple.m3" }, GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.execute.form", GrowthOwner.Ian, "전투 기술 / 유리 쇄도", "집행의 직선", "지정한 적을 향한 가는 직선 기술이다. 처치하면 재사용 대기시간을 초기화하고 이번 턴의 추가 기술 사용을 한 번 허용한다. 추가 사용으로 또 처치해도 세 번째 기술은 허용하지 않는다.", "처치하지 못한 단독 적에게는 재사용 연쇄가 생기지 않는다.", 1, "전투 기술 형태", "전투 기술", "유리 쇄도", "", "", 0, System.Array.Empty<string>(), 0, System.Array.Empty<string>(), GrowthImplementationStatus.PrototypePartial),
                new GrowthNodeDefinition("ian.execute.m1", GrowthOwner.Ian, "전투 기술 / 유리 쇄도", "추적 서명", "작도로 서명을 남긴 적을 선택하면 안전한 착지 후보를 적 반대편까지 넓힌다. 공격 자체가 이동 장애물이나 필드 경계를 무시하지는 않는다.", "", 1, "기술 특성", "", "", "", "ian.execute", 2, new[] { "ian.execute.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.execute.m2", GrowthOwner.Ian, "전투 기술 / 유리 쇄도", "파열 집행", "기존 파열 일부를 즉시 소비해 기술에 싣는다. 같은 파열을 뒤의 그래프 피해에 또 더하지 않는다.", "", 1, "기술 특성", "", "", "", "ian.execute", 2, new[] { "ian.execute.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
