                new GrowthNodeDefinition("ian.execute.awaken", GrowthOwner.Ian, "전투 기술 / 유리 쇄도", "검은 종결선", "집행 뒤 마지막 착지점과 기록 기준점 사이에 종결선을 만든다. 다음 실제 작도가 이 선을 가로지르면 살아남은 지정 대상에게 보류한 집행을 한 번 정산한다.", "", 2, "기술 각성", "", "", "", "", 0, new[] { "ian.execute.form" }, 2, new[] { "ian.execute.m1", "ian.execute.m2", "ian.execute.m3" }, GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.exchange.form", GrowthOwner.Ian, "전투 기술 / 유리 쇄도", "거울 교환", "대상 뒤의 안전 지점으로 전이하고 출발점에 거울 흔적을 남긴다. 대상 주변에는 작은 파열이 생긴다. 이미 놓은 파편의 기준점은 자동으로 따라오지 않는다.", "이동 후 기존 조립과 자기 위치가 어긋날 수 있고, 뒤쪽에 안전 지점이 없으면 가까운 유효 후보로 제한된다.", 1, "전투 기술 형태", "전투 기술", "유리 쇄도", "", "", 0, System.Array.Empty<string>(), 0, System.Array.Empty<string>(), GrowthImplementationStatus.PrototypePartial),
                new GrowthNodeDefinition("ian.exchange.m1", GrowthOwner.Ian, "전투 기술 / 유리 쇄도", "쌍방 서명", "다음 작도의 자가 적중 위치를 현재 몸과 출발 흔적 중 하나로 고른다. 두 곳을 모두 맞혀도 자가 효과는 한 번이다.", "", 1, "기술 특성", "", "", "", "ian.exchange", 2, new[] { "ian.exchange.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.exchange.m2", GrowthOwner.Ian, "전투 기술 / 유리 쇄도", "역상 위치", "전이를 확정하기 전에 기존 식을 출발점과 도착점의 중간축에 대칭시킬 수 있다. 카드 능력을 다시 사용하지 않는다.", "", 1, "기술 특성", "", "", "", "ian.exchange", 2, new[] { "ian.exchange.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.exchange.m3", GrowthOwner.Ian, "전투 기술 / 유리 쇄도", "되닫힌 문", "이번 턴의 실제 방출 직후, 출발 흔적으로 복귀하는 예약을 걸 수 있다. 복귀 지점과 남을 조준 위험을 미리 보여 주며 추가 무적이나 이동 횟수는 주지 않는다.", "", 1, "기술 특성", "", "", "", "ian.exchange", 2, new[] { "ian.exchange.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.exchange.awaken", GrowthOwner.Ian, "전투 기술 / 유리 쇄도", "두 세계의 교환", "출발 흔적과 도착점 사이에 작은 거울 영역을 만든다. 한 방출을 두 위치에 나누거나 한 위치에 모아 쓰며, 복제 전체 예산 안에서 처리한다.", "", 2, "기술 각성", "", "", "", "", 0, new[] { "ian.exchange.form" }, 2, new[] { "ian.exchange.m1", "ian.exchange.m2", "ian.exchange.m3" }, GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.brand.form", GrowthOwner.Ian, "전투 기술 / 흑유리 각인", "파쇄의 낙인", "적 한 명에게 낙인을 남긴다. 다음 그래프가 직접 맞히면 낙인이 깨지며 그 적 주변에 작은 파열을 만들고 사라진다.", "기술 자체의 즉시 피해가 낮고 그래프가 빗나가면 후속 공격을 얻지 못한다.", 1, "전투 기술 형태", "전투 기술", "흑유리 각인", "", "", 0, System.Array.Empty<string>(), 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.brand.m1", GrowthOwner.Ian, "전투 기술 / 흑유리 각인", "살아 있는 주석", "낙인을 적 몸에 붙여 이동을 따라가게 한다. 기존 위치에는 아무 판정도 남지 않는다.", "", 1, "기술 특성", "", "", "ian.brand.anchor_mode", "ian.brand", 2, new[] { "ian.brand.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.brand.m2", GrowthOwner.Ian, "전투 기술 / 흑유리 각인", "못 박힌 주석", "낙인을 적이 있던 좌표에 고정한다. 적이 벗어나도 그래프가 그 좌표를 지나면 작은 파열이 일어나므로 이동 예측용으로 쓴다. 살아 있는 주석과 함께 장착하지 않는다.", "", 1, "기술 특성", "", "", "ian.brand.anchor_mode", "ian.brand", 2, new[] { "ian.brand.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.brand.m3", GrowthOwner.Ian, "전투 기술 / 흑유리 각인", "내부 파쇄", "낙인 대상이 단독 적이면 주변 파열을 대상 내부의 후속 타격으로 바꾼다. 주변 광역 효과와 동시에 받지는 않는다.", "", 1, "기술 특성", "", "", "", "ian.brand", 2, new[] { "ian.brand.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.brand.awaken", GrowthOwner.Ian, "전투 기술 / 흑유리 각인", "대균열의 문장", "낙인 폭발 뒤 남은 짧은 균열선을 다음 작도의 연결 대상으로 만든다. 이어지는 작도가 새 적이나 아직 살아 있는 원래 대상을 맞혀야 한 번만 다시 갈라진다.", "", 2, "기술 각성", "", "", "", "", 0, new[] { "ian.brand.form" }, 2, new[] { "ian.brand.m1", "ian.brand.m2", "ian.brand.m3" }, GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.link.form", GrowthOwner.Ian, "전투 기술 / 흑유리 각인", "흑경 연결", "적 두 명, 또는 적 한 명과 설치물 하나를 짧은 흑경선으로 잇는다. 실제 그래프가 연결선을 건드리면 그 선을 통해 제한된 출력을 대상에게 보낼 수 있다.", "연결이 없는 적에게는 보상이 없고 두 대상 사이가 너무 멀면 연결할 수 없다.", 1, "전투 기술 형태", "전투 기술", "흑유리 각인", "", "", 0, System.Array.Empty<string>(), 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
