                new GrowthNodeDefinition("ian.ash.m1", GrowthOwner.Ian, "전투 기술 / 흑유리 각인", "잔불 수금", "봉인된 적이 다른 공격으로 죽으면 보류한 잔불을 근처 적 한 명에게 옮긴다. 적이 없으면 소멸하고 회복이나 공명으로 전환하지 않는다.", "", 1, "기술 특성", "", "", "", "ian.ash", 2, new[] { "ian.ash.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
