                new GrowthNodeDefinition("ian.u.collapse.form", GrowthOwner.Ian, "궁극기 / 성좌 붕괴", "성좌 붕괴", "이번 실제 작도가 적을 맞힌 지점에서 짧은 균열 파열을 일으킨다. 큰 식을 만들수록 무조건 화면 전체가 폭발하는 것이 아니라 실제 적중 지점과 연결된 작은 영역만 갈라진다.", "자가 방어보다 다중 적중과 파열 정산에 집중하는 즉발형이다.", 2, "궁극기 형태", "궁극기", "성좌 붕괴", "", "", 0, System.Array.Empty<string>(), 0, System.Array.Empty<string>(), GrowthImplementationStatus.PrototypePartial),
