                new GrowthNodeDefinition("ian.u.illusion.m1", GrowthOwner.Ian, "궁극기 / 흑경 반전", "하나의 진실", "두 도안 중 적이 더 많이 맞는 하나에 이번 출력을 집중하고 다른 도안은 방어 대리 판정만 남긴다.", "", 1, "궁극기 성질 변형", "", "", "ian.u.illusion.augment", "", 0, new[] { "ian.u.illusion.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
