                new GrowthNodeDefinition("luna.u.embrace.form", GrowthOwner.Luna, "궁극기 / 만월의 포옹", "만월의 포옹", "이번 그래프 주변의 제한된 폭을 달의 성역으로 만들고 실제 자가 적중에서 정화·보호막·회복을 얻는다. 성역은 다음 턴까지 지점으로 남지만 원본 회복을 매 턴 반복하지 않는다.", "성역 밖에서 싸우면 후속 방어를 얻지 못하고 큰 즉발 공격을 포기한다.", 2, "궁극기 형태", "궁극기", "만월의 포옹", "", "", 0, System.Array.Empty<string>(), 0, System.Array.Empty<string>(), GrowthImplementationStatus.PrototypePartial),
                new GrowthNodeDefinition("luna.u.embrace.m1", GrowthOwner.Luna, "궁극기 / 만월의 포옹", "머무는 만월", "성역 안에 머무른 다음 실제 방출에 작은 방어 보완을 한 번 적용한다. 피해를 주지 않고 턴만 넘겨 무한 회복하지 않는다.", "", 1, "궁극기 성질 변형", "", "", "luna.u.embrace.augment", "", 0, new[] { "luna.u.embrace.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.u.embrace.m2", GrowthOwner.Luna, "궁극기 / 만월의 포옹", "나눠진 달빛", "성역의 방어 지점을 관측 위성에도 분배한다. 몸과 위성을 합쳐 회복·보호막 총량을 공유한다.", "", 1, "궁극기 성질 변형", "", "", "luna.u.embrace.augment", "", 0, new[] { "luna.u.embrace.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.u.white.form", GrowthOwner.Luna, "궁극기 / 만월의 포옹", "백야", "궁극기 도안 주변의 작은 달무리를 다음 두 턴 동안 루나의 확정 이동량만큼 함께 옮긴다. 고정 성역 대신 이동하는 방어·작도 기준 영역이 된다.", "일반 이동을 쓰지 않으면 지점이 그대로이며 루나가 안전해져도 실제 적중이 없으면 자동 공격하지 않는다.", 2, "궁극기 형태", "궁극기", "만월의 포옹", "", "", 0, System.Array.Empty<string>(), 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.u.white.m1", GrowthOwner.Luna, "궁극기 / 만월의 포옹", "함께 뜨는 달", "달무리가 몸을 따라가며 다음 자가 적중을 보완한다. 독립 설치 성역은 남기지 않는다.", "", 1, "궁극기 성질 변형", "", "", "luna.u.white.augment", "", 0, new[] { "luna.u.white.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.u.white.m2", GrowthOwner.Luna, "궁극기 / 만월의 포옹", "뒤에 남은 달", "달무리가 도착점 대신 직전 이동 출발점에 남는다. 전장에 두 달무리를 동시에 만들지 않고 공격 기준점을 분리한다.", "", 1, "궁극기 성질 변형", "", "", "luna.u.white.augment", "", 0, new[] { "luna.u.white.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.u.twin.form", GrowthOwner.Luna, "궁극기 / 만월의 포옹", "쌍월 동조", "이번 궁극기에서 두 관측점을 임시로 만든다. 한쪽은 공격 도안, 다른 쪽은 방어 도안으로 역할을 나누며 원래 작도와 카드 능력 예산을 공유한다.", "관측점이 두 배라고 피해·회복도 두 배가 되지 않으며 두 역할의 위치를 잘 골라야 한다.", 2, "궁극기 형태", "궁극기", "만월의 포옹", "", "", 0, System.Array.Empty<string>(), 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.u.twin.m1", GrowthOwner.Luna, "궁극기 / 만월의 포옹", "살과 달", "방어 도안을 몸에 고정하고 공격 도안만 원격으로 펼친다. 몸이 방어 도안에 실제로 닿아야 자가 효과를 받는다.", "", 1, "궁극기 성질 변형", "", "", "luna.u.twin.augment", "", 0, new[] { "luna.u.twin.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.u.twin.m2", GrowthOwner.Luna, "궁극기 / 만월의 포옹", "먼 곳의 피난처", "공격 도안을 몸 근처에 두고 방어 도안을 위성에 둔다. 위성을 실제로 맞혀야 대리 자가 효과를 얻는다.", "", 1, "궁극기 성질 변형", "", "", "luna.u.twin.augment", "", 0, new[] { "luna.u.twin.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.u.blade.form", GrowthOwner.Luna, "궁극기 / 그믐의 칼날", "그믐의 칼날", "이번 그래프를 따라 서로 다른 두 방향의 초승달 절단이 지나간다. 한 번의 출력을 두 구간으로 배분하여 보호막과 후속 타격 순서를 설계한다.", "빠른 한 방보다 분할 공격이며 카드 상태 효과와 공명은 두 번 발동하지 않는다.", 2, "궁극기 형태", "궁극기", "그믐의 칼날", "", "", 0, System.Array.Empty<string>(), 0, System.Array.Empty<string>(), GrowthImplementationStatus.PrototypePartial),
                new GrowthNodeDefinition("luna.u.blade.m1", GrowthOwner.Luna, "궁극기 / 그믐의 칼날", "앞선 그믐", "첫 절단에서 기존 파열을 소비하고 뒤의 절단은 남은 순수 피해만 준다. 같은 파열을 두 번 소비하지 않는다.", "", 1, "궁극기 성질 변형", "", "", "luna.u.blade.augment", "", 0, new[] { "luna.u.blade.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.u.blade.m2", GrowthOwner.Luna, "궁극기 / 그믐의 칼날", "늦은 그믐", "첫 절단은 약한 준비 타격, 둘째는 다음 적 행동 후 정산으로 바꾼다. 상대 위치가 바뀌면 후속 절단은 빗나갈 수 있다.", "", 1, "궁극기 성질 변형", "", "", "luna.u.blade.augment", "", 0, new[] { "luna.u.blade.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.u.devour.form", GrowthOwner.Luna, "궁극기 / 그믐의 칼날", "월식 포식", "이번 그래프가 실제로 맞힌 적의 잔불·노출·파열 가운데 자신이 부여한 상태 일부를 소비해 제한된 직접 피해와 자기 보호 중 하나로 바꾼다.", "상태를 모아야 강하고 소비한 지속 피해와 미래 파열은 더 이상 남지 않는다.", 2, "궁극기 형태", "궁극기", "그믐의 칼날", "", "", 0, System.Array.Empty<string>(), 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.u.devour.m1", GrowthOwner.Luna, "궁극기 / 그믐의 칼날", "검은 식사", "소비한 상태 예산을 단일 적의 추가 피해로 집중한다. 회복·보호막으로 다시 전환하지 않는다.", "", 1, "궁극기 성질 변형", "", "", "luna.u.devour.augment", "", 0, new[] { "luna.u.devour.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.u.devour.m2", GrowthOwner.Luna, "궁극기 / 그믐의 칼날", "희어진 식사", "직접 피해 전환 대신 실제 자가 적중에서 보호막을 얻는다. 적만 맞힌 궁극기로 원격 무조건 회복하지 않는다.", "", 1, "궁극기 성질 변형", "", "", "luna.u.devour.augment", "", 0, new[] { "luna.u.devour.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.u.meteor.form", GrowthOwner.Luna, "궁극기 / 그믐의 칼날", "유성우", "이번 작도선 위에서 최대 세 개의 위치를 지정해 다음 적 행동 후 유성을 떨어뜨린다. 적의 공개 이동 목적지와 현재 도안의 관계를 읽는 지연 공격이다.", "지연 전에 이동하는 적은 피할 수 있고 무조건 추적 유성이 아니다.", 2, "궁극기 형태", "궁극기", "그믐의 칼날", "", "", 0, System.Array.Empty<string>(), 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.u.meteor.m1", GrowthOwner.Luna, "궁극기 / 그믐의 칼날", "별자리 폭격", "세 낙하 위치를 현재 천문 도구 연결선의 교점 중에서 고를 수 있다. 실제 연결이 없는 좌표에는 찍지 못한다.", "", 1, "궁극기 성질 변형", "", "", "luna.u.meteor.augment", "", 0, new[] { "luna.u.meteor.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.u.meteor.m2", GrowthOwner.Luna, "궁극기 / 그믐의 칼날", "단 하나의 유성", "세 낙하를 한 곳의 큰 유성으로 합친다. 총 출력 예산은 유지하되 더 좁은 단일 목표에 집중한다.", "", 1, "궁극기 성질 변형", "", "", "luna.u.meteor.augment", "", 0, new[] { "luna.u.meteor.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.u.stop.form", GrowthOwner.Luna, "궁극기 / 월식 정지", "월식 정지", "이번 그래프에 맞은 적의 위치를 짧게 고정하고 현재 도안을 다음 조립의 조정 기준으로 남긴다. 이동만 막으며 적의 공격·잔불·턴 경과는 정상 진행된다.", "고정만으로 공격을 피할 수 없고 이동하지 않는 적에게는 위치 제어 이득이 작다.", 2, "궁극기 형태", "궁극기", "월식 정지", "", "", 0, System.Array.Empty<string>(), 0, System.Array.Empty<string>(), GrowthImplementationStatus.PrototypePartial),
                new GrowthNodeDefinition("luna.u.stop.m1", GrowthOwner.Luna, "궁극기 / 월식 정지", "시간 회수", "궁극기 방출 시 기술 대기시간 하나를 초기화한다. 사용 가능 횟수 한도는 별개로 적용한다.", "", 1, "궁극기 성질 변형", "", "", "luna.u.stop.augment", "", 0, new[] { "luna.u.stop.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.u.stop.m2", GrowthOwner.Luna, "궁극기 / 월식 정지", "정지 좌표", "고정된 적의 위치 하나를 다음 실제 작도의 원격 기준점으로 지정할 수 있다. 적을 강제로 자기 쪽으로 옮기지는 않는다.", "", 1, "궁극기 성질 변형", "", "", "luna.u.stop.augment", "", 0, new[] { "luna.u.stop.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.u.align.form", GrowthOwner.Luna, "궁극기 / 월식 정지", "천체 정렬", "완성한 그래프의 가까운 유효 지점으로 일반 적을 제한된 거리만큼 끌어 배치하고 그 위치에서 궁극기 작도를 정산한다. 이동 전후와 예상 적중을 함께 미리 본다.", "강제 이동 면역 적은 옮기지 않고 짧은 파열만 남긴다. 실제 그래프가 빗나간 면역 적을 자동 명중으로 취급하지 않는다.", 2, "궁극기 형태", "궁극기", "월식 정지", "", "", 0, System.Array.Empty<string>(), 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.u.align.m1", GrowthOwner.Luna, "궁극기 / 월식 정지", "외곽 천문", "적을 그래프에서 더 바깥쪽인 후보 지점으로 배치한다. 다중 궤도·원주 도안과 맞추는 형태다.", "", 1, "궁극기 성질 변형", "", "", "luna.u.align.augment", "", 0, new[] { "luna.u.align.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.u.align.m2", GrowthOwner.Luna, "궁극기 / 월식 정지", "내곽 천문", "적을 그래프의 기준점에 더 가까운 유효 후보로 배치한다. 작은 도안과 압축 공격에 맞추되 이동 상한을 지킨다.", "", 1, "궁극기 성질 변형", "", "", "luna.u.align.augment", "", 0, new[] { "luna.u.align.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.u.timeless.form", GrowthOwner.Luna, "궁극기 / 월식 정지", "시계 없는 밤", "공명 6 궁극기의 첫 방출 뒤 남은 손패만으로 추가 작도 한 번을 준비하고 방출한다. 두 번째 방출이 끝나야 적이 행동한다. 추가 방출에는 추가 드로우·이동 갱신·기술 쿨타임 감소·새 궁극기 사용이 없다.", "첫 작도에서 손패를 다 쓰면 두 번째 공격을 만들기 어렵다. 추가 응축은 허용하지 않고 언제든 적 행동으로 넘길 수 있다.", 2, "궁극기 형태", "궁극기", "월식 정지", "", "", 0, System.Array.Empty<string>(), 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
