                new GrowthNodeDefinition("luna.u.timeless.m2", GrowthOwner.Luna, "궁극기 / 월식 정지", "정해진 밤", "두 번째 작도를 새 카드 조립 대신 첫 도안의 제한된 기하학 재현으로 바꾼다. 쉬워지는 대신 새로운 카드 효과·드로우를 얻지 않는다.", "", 1, "궁극기 성질 변형", "", "", "luna.u.timeless.augment", "", 0, new[] { "luna.u.timeless.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.bridge.01", GrowthOwner.Ian, "혼합 성좌", "파열의 회랑", "삼중 유리길의 남은 선을 통해 파쇄 낙인을 발동할 수 있다. 그래프가 낙인 몸 대신 회랑과 실제로 연결된 낙인 지점을 지나야 한다.", "", 2, "교차 연결", "", "", "", "", 0, new[] { "ian.triple.form", "ian.brand.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.bridge.02", GrowthOwner.Ian, "혼합 성좌", "집행의 대리인", "유리 쐐기가 먼저 맞힌 적을 집행의 우선 대상으로 표시한다. 쐐기 자체 처치가 집행의 추가 행동을 발동하지는 않는다.", "", 2, "교차 연결", "", "", "", "", 0, new[] { "ian.execute.form", "ian.spike.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.bridge.03", GrowthOwner.Ian, "혼합 성좌", "거울 속 서가", "거울 교환의 출발 흔적을 거울 서가의 고정 재현 위치로 쓴다. 안전 복귀와 원격 공격이 같은 지점을 공유한다.", "", 2, "교차 연결", "", "", "", "", 0, new[] { "ian.exchange.form", "ian.shelf.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.bridge.04", GrowthOwner.Ian, "혼합 성좌", "연결된 방벽", "흑경 연결의 한 끝을 검은 성벽으로 삼는다. 벽이 실제 완충한 다음 그래프만 연결된 적에게 제한된 반격 출력을 보낸다.", "", 2, "교차 연결", "", "", "", "", 0, new[] { "ian.link.form", "ian.wall.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.bridge.05", GrowthOwner.Ian, "혼합 성좌", "재의 정원", "유리 쐐기로 봉인된 적을 실제 타격하면 재의 봉인 폭발을 그 쐐기 위치로 옮긴다. 보류 잔불은 한 번만 소비한다.", "", 2, "교차 연결", "", "", "", "", 0, new[] { "ian.ash.form", "ian.spike.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.bridge.06", GrowthOwner.Ian, "혼합 성좌", "도안 위의 낙인", "거울 서가의 재현이 낙인 지점을 직접 지나도 낙인을 소비할 수 있다. 낙인 폭발은 새 서가 재현을 만들지 않는다.", "", 2, "교차 연결", "", "", "", "", 0, new[] { "ian.brand.form", "ian.shelf.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.bridge.07", GrowthOwner.Ian, "혼합 성좌", "검은 필사본", "집행의 마지막 직선을 잔상 도안의 한 부분으로 보관할 수 있다. 보관 집행에는 처치 초기화·궁극기·기술 공명이 없다.", "", 2, "교차 연결", "", "", "", "", 0, new[] { "ian.archive.core", "ian.execute.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.bridge.08", GrowthOwner.Ian, "혼합 성좌", "부서지는 성역", "수호자의 보존 보호막을 성좌 붕괴의 작은 균열 한 곳에 투자한다. 소비량에 상한을 두고 자기 방어와 공격 전환을 동시에 받지 않는다.", "", 2, "교차 연결", "", "", "", "", 0, new[] { "ian.citadel.core", "ian.u.collapse.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.bridge.09", GrowthOwner.Ian, "혼합 성좌", "결산의 임계점", "균열 기록자의 결산 유예로 보류한 파열을 임계점의 한 대상에게 소비한다. 다른 적들의 파열을 전장 전체에서 원격 회수하지 않는다.", "", 2, "교차 연결", "", "", "", "", 0, new[] { "ian.inscription.m3", "ian.u.critical.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.bridge.10", GrowthOwner.Ian, "혼합 성좌", "재현된 적의 문장", "적의 문장을 잔상 도안 한 슬롯으로 보관한다. 다음 호출은 원래 궁극기가 아닌 제한된 조준 원 공격으로 처리한다.", "", 2, "교차 연결", "", "", "", "", 0, new[] { "ian.archive.core", "ian.u.enemytext.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("ian.bridge.11", GrowthOwner.Ian, "혼합 성좌", "가시의 흑유리", "반격 작도를 흑유리화의 작은 방벽에서 발사한다. 적 공격 하나당 한 번, 전체 턴 상한 안에서만 재현한다.", "", 2, "교차 연결", "", "", "", "", 0, new[] { "common.self.07", "ian.u.glassbody.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
