                new GrowthNodeDefinition("luna.bridge.01", GrowthOwner.Luna, "혼합 성좌", "공전하는 만월", "만월 착지로 놓인 발자국을 월륜 회전의 임시 중심으로 삼는다. 착지 후 기존 식을 회전시켜 다음 공격 대상을 바꾼다.", "", 2, "교차 연결", "", "", "", "", 0, new[] { "luna.fulljump.form", "luna.rotate.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.bridge.02", GrowthOwner.Luna, "혼합 성좌", "회귀 관측", "초승달 회귀의 출발점을 월면 관측기의 다음 위치로 예약한다. 귀환 직후 몸과 도구가 중첩돼도 자가 효과를 두 번 받지 않는다.", "", 2, "교차 연결", "", "", "", "", 0, new[] { "luna.return.form", "luna.observatory.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.bridge.03", GrowthOwner.Luna, "혼합 성좌", "별의 날실", "별무리 전이의 경유선 하나를 은하 직조의 실로 전환한다. 원래 경유선과 새 실의 피해를 중복 복제하지 않는다.", "", 2, "교차 연결", "", "", "", "", 0, new[] { "luna.chain.form", "luna.weave.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.bridge.04", GrowthOwner.Luna, "혼합 성좌", "쌍성의 조석", "쌍성추의 두 지점을 성운 견인의 안쪽·바깥쪽 기준으로 쓴다. 적은 미리 본 한 지점으로만 이동하고 두 추에 동시에 끌려가지 않는다.", "", 2, "교차 연결", "", "", "", "", 0, new[] { "luna.pull.form", "luna.pendulum.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.bridge.05", GrowthOwner.Luna, "혼합 성좌", "역조의 관측자", "월면 관측기를 조석 반전의 중심으로 사용할 때 그 주변의 자가 대리점도 새 위치를 따른다. 이동 불가 지형에서는 원래 유효 지점을 유지한다.", "", 2, "교차 연결", "", "", "", "", 0, new[] { "luna.tide.form", "luna.observatory.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.bridge.06", GrowthOwner.Luna, "혼합 성좌", "회전하는 베틀", "월륜 회전으로 식을 조정하면 은하 직조의 실 중 하나도 같은 각도로 돌릴 수 있다. 실 끝점이 실제 기점에 남는 유효 경우에만 허용한다.", "", 2, "교차 연결", "", "", "", "", 0, new[] { "luna.rotate.form", "luna.weave.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.bridge.07", GrowthOwner.Luna, "혼합 성좌", "만월을 걷는 자", "궤도 조율자의 확정 이동으로 만월의 포옹 성역의 짧은 구간만 옮길 수 있다. 성역 전체를 무제한 확장하지 않는다.", "", 2, "교차 연결", "", "", "", "", 0, new[] { "luna.orbit.core", "luna.u.embrace.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.bridge.08", GrowthOwner.Luna, "혼합 성좌", "그믐의 박자", "삭에서 사용한 그믐의 칼날은 앞 절단, 만월에서 사용하면 뒤 절단을 강조하는 제한된 배분을 고른다. 총 궁극기 출력 예산은 같다.", "", 2, "교차 연결", "", "", "", "", 0, new[] { "luna.phase.core", "luna.u.blade.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.bridge.09", GrowthOwner.Luna, "혼합 성좌", "쌍월 관측소", "쌍월 동조의 임시 관측점 하나를 기존 쌍성 위성 위치로 옮긴다. 도구 수를 늘리지 않고 기존 역할을 교체한다.", "", 2, "교차 연결", "", "", "", "", 0, new[] { "luna.binary.core", "luna.u.twin.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.bridge.10", GrowthOwner.Luna, "혼합 성좌", "떨어지는 천구", "성운 견인으로 유성우 낙하 위치에 적을 유도한다. 낙하 예약 후 견인은 다음 정상 기술 행동을 쓰며 즉시 추가 기술을 주지 않는다.", "", 2, "교차 연결", "", "", "", "", 0, new[] { "luna.pull.form", "luna.u.meteor.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
                new GrowthNodeDefinition("luna.bridge.11", GrowthOwner.Luna, "혼합 성좌", "여백의 정렬", "여백의 법칙을 쓸 때 천체 정렬의 합법적 이동 후보를 선이 아니라 제한된 빈 영역의 경계로 바꾼다. 이동 면역 적의 강제 명중은 없다.", "", 2, "교차 연결", "", "", "", "", 0, new[] { "common.geometry.08", "luna.u.align.form" }, 0, System.Array.Empty<string>(), GrowthImplementationStatus.Planned),
